import{_ as a,a0 as s,w as p,s as l,ao as u,I as i,x as n,a1 as r,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"Linux有問必答：如何在Linux中修改環境變量PATH | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在Linux中修改環境變量PATH | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在Linux中修改環境變量PATH | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在Linux中修改環境變量PATH | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150413 Linux FAQs with Answers--How to change PATH environment variable on Linux","title":"Linux有問必答：如何在Linux中修改環境變量PATH","tag":"201505","desc":""},"relativePath":"201505/20150413 Linux FAQs with Answers--How to change PATH environment variable on Linux.md","filePath":"[post].md"}'),d={name:"201505/20150413 Linux FAQs with Answers--How to change PATH environment variable on Linux.md"};function T(x,e,b,m,A,h){const o=s("Link");return p(),l("div",null,[e[13]||(e[13]=u(`<h1 id="linux有問必答-如何在linux中修改環境變量path" tabindex="-1">Linux有問必答：如何在Linux中修改環境變量PATH <a class="header-anchor" href="#linux有問必答-如何在linux中修改環境變量path" aria-label="Permalink to “Linux有問必答：如何在Linux中修改環境變量PATH”">​</a></h1><blockquote><p><strong>提問</strong>: 當我試着運行一個程序時，它提示“command not found”。 但這個程序就在/usr/local/bin下。我該如何添加/usr/local/bin到我的PATH變量下，這樣我就可以不用指定路徑來運行這個命令了。</p></blockquote><p>在Linux中，PATH環境變量保存了一系列的目錄用於用户在輸入的時候搜索命令。PATH變量的值由一系列的由分號分隔的絕對路徑組成。每個用户都有特定的PATH環境變量（由系統級的PATH變量初始化）。</p><p>要檢查用户的環境變量，用户模式下運行下面的命令：</p><pre><code>$ echo $PATH
</code></pre><hr><pre><code>/usr/lib64/qt-3.3/bin:/bin:/usr/bin:/usr/sbin:/sbin:/home/xmodulo/bin
</code></pre><p>或者運行：</p><pre><code>$ env | grep PATH
</code></pre><hr><pre><code>PATH=/usr/lib64/qt-3.3/bin:/bin:/usr/bin:/usr/sbin:/sbin:/home/xmodulo/bin
</code></pre><p>如果你的命令不存在於上面任何一個目錄內，shell就會拋出一個錯誤信息：“command not found”。</p><p>如果你想要添加一個另外的目錄（比如：/usr/local/bin）到你的PATH變量中，你可以用下面這些命令。</p><h3 id="為特定用户修改path環境變量" tabindex="-1">為特定用户修改PATH環境變量 <a class="header-anchor" href="#為特定用户修改path環境變量" aria-label="Permalink to “為特定用户修改PATH環境變量”">​</a></h3><p>如果你只想在當前的登錄會話中臨時地添加一個新的目錄（比如：/usr/local/bin）給用户的默認搜索路徑，你只需要輸入下面的命令。</p><pre><code>$ PATH=$PATH:/usr/local/bin
</code></pre><p>檢查PATH是否已經更新：</p><pre><code>$ echo $PATH
</code></pre><hr><pre><code>/usr/lib64/qt-3.3/bin:/bin:/usr/bin:/usr/sbin:/sbin:/home/xmodulo/bin:/usr/local/bin
</code></pre><p>更新後的PATH會在當前的會話一直有效。然而，更改將在新的會話中失效。</p><p>如果你想要永久更改PATH變量，用編輯器打開~/.bashrc (或者 ~/.bash_profile)，接着在最後添加下面這行。</p><pre><code>export PATH=$PATH:/usr/local/bin
</code></pre><p>接着運行下面這行永久激活更改：</p><pre><code>$ source ~/.bashrc (或者 source ~/.bash_profile)
</code></pre><h3 id="改變系統級的環境變量" tabindex="-1">改變系統級的環境變量 <a class="header-anchor" href="#改變系統級的環境變量" aria-label="Permalink to “改變系統級的環境變量”">​</a></h3><p>如果你想要永久添加/usr/local/bin到系統級的PATH變量中，像下面這樣編輯/etc/profile。</p><pre><code>$ sudo vi /etc/profile
</code></pre><hr><pre><code>export PATH=$PATH:/usr/local/bin
</code></pre><p>你重新登錄後，更新的環境變量就會生效了。</p><hr>`,32)),i("p",null,[e[1]||(e[1]=n("via: ",-1)),r(o,{href:"http://ask.xmodulo.com/change-path-environment-variable-linux.html"},{default:t(()=>[...e[0]||(e[0]=[n("http://ask.xmodulo.com/change-path-environment-variable-linux.html",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=n("作者：",-1)),r(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:t(()=>[...e[2]||(e[2]=[n("Dan Nanni",-1)])]),_:1}),e[6]||(e[6]=n(" 譯者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:t(()=>[...e[3]||(e[3]=[n("geekpi",-1)])]),_:1}),e[7]||(e[7]=n(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[n("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=n("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[n("LCTT",-1)])]),_:1}),e[11]||(e[11]=n(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[n("Linux中國",-1)])]),_:1}),e[12]||(e[12]=n(" 榮譽推出",-1))])])}const L=a(d,[["render",T]]);export{c as __pageData,L as default};
